use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200001
    let mut sieve = []
    for i in 0..limit { sieve.push(true) }
    let mut counts = []
    let mut largest = []
    let mut c: int = 0
    let mut last: int = 0
    for i in 0..limit {
        if i >= 2 && sieve[i] {
            c += 1
            last = i
            let mut j: int = i * 2
            while j < limit {
                sieve[j] = false
                j += i
            }
        }
        counts.push(c)
        largest.push(last)
    }
    let mut first = true
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n = s.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

